package com.bank.gw;

import java.util.logging.*;

public class GatewayDemo {
    private static final Logger log = Logger.getLogger("Gateway");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        Gateway igw = new InternetGateway();
        Gateway nat = new NatGateway();
        TrafficRouter router = new TrafficRouter();

        // Public load balancer via IGW.
        log.info(() -> "ALB inbound via IGW:  " + router.allowed(igw, "INBOUND"));
        log.info(() -> "ALB outbound via IGW: " + router.allowed(igw, "OUTBOUND"));

        // Private database via NAT.
        log.info(() -> "DB outbound via NAT (patch/API): " + router.allowed(nat, "OUTBOUND"));
        log.warning(() -> "DB inbound via NAT (attacker):   " + router.allowed(nat, "INBOUND"));
    }
}

// ─── Would be in Gateway.java ───
interface Gateway {
    boolean permits(String direction);
    String name();
}

// ─── Would be in InternetGateway.java ───
class InternetGateway implements Gateway {
    public boolean permits(String direction) { return true; }  // two-way
    public String name() { return "InternetGateway"; }
}

// ─── Would be in NatGateway.java ───
class NatGateway implements Gateway {
    // Only outbound-initiated connections; replies to them return, inbound blocked.
    public boolean permits(String direction) { return "OUTBOUND".equals(direction); }
    public String name() { return "NatGateway"; }
}

// ─── Would be in TrafficRouter.java ───
class TrafficRouter {
    String allowed(Gateway g, String direction) {
        return g.permits(direction)
            ? "ALLOWED via " + g.name()
            : "BLOCKED via " + g.name();
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n", r.getMillis(), r.getLevel(), r.getMessage());
    }
}
